-- ========== RE-EXEC: kill old instance completely ==========
local ENV = (getgenv and getgenv()) or _G
local HUB_KEY = "PawZHub_GreedyGrowers"

local function DestroyHubGuis()
    local names = { "PawZHub", "PawHub", "PawZHubGG", "PawZHubLoader", "PawZHubToast" }
    local parents = {}
    pcall(function() parents[#parents + 1] = CoreGui end)
    pcall(function()
        local pg = Player:FindFirstChild("PlayerGui")
        if pg then parents[#parents + 1] = pg end
    end)
    for _, parent in ipairs(parents) do
        for _, name in ipairs(names) do
            pcall(function()
                local g = parent:FindFirstChild(name)
                if g then g:Destroy() end
            end)
        end
        -- also destroy any ScreenGui tagged by us
        pcall(function()
            for _, child in ipairs(parent:GetChildren()) do
                if child:IsA("ScreenGui") and child:GetAttribute("PawZHubScript") == true then
                    child:Destroy()
                end
            end
        end)
    end
end

if type(ENV[HUB_KEY]) == "table" and type(ENV[HUB_KEY].Unload) == "function" then
    pcall(function() ENV[HUB_KEY]:Unload() end)
end
DestroyHubGuis()
task.wait(0.05)

local HubInstance = {
    connections = {},
    stopped = false,
}
function HubInstance:AddConnection(conn)
    if conn then
        self.connections[#self.connections + 1] = conn
    end
    return conn
end
function HubInstance:ForceAllFeaturesOff(cfg)
    cfg = cfg or self.Config
    if type(cfg) ~= "table" then return end
    cfg.AutoBuy = false
    cfg.AutoPlant = false
    cfg.AutoHarvest = false
    cfg.AutoCollect = false
    cfg.AutoSell = false
    cfg.AutoFertilizer = false
    cfg.AutoRebirth = false
    cfg.AutoFeedPet = false
    cfg.AutoPlaceEgg = false
    cfg.AutoEquipPet = false
    cfg.AutoServerHop = false
    cfg.AntiAFK = false
    cfg.SpeedEnabled = false
end

function HubInstance:Unload()
    if self.stopped then return end
    self.stopped = true
    local eng = self.FeatureEngine
    local hop = self.ServerHop
    local cfg = self.Config
    pcall(function()
        if eng and eng.Stop then eng:Stop() end
    end)
    pcall(function()
        if hop and hop.Stop then hop:Stop() end
        if hop then hop.Active = false end
    end)
    self:ForceAllFeaturesOff(cfg)
    for _, conn in ipairs(self.connections) do
        pcall(function()
            if typeof(conn) == "RBXScriptConnection" then
                conn:Disconnect()
            elseif type(conn) == "table" and conn.Disconnect then
                conn:Disconnect()
            end
        end)
    end
    self.connections = {}
    DestroyHubGuis()
end
ENV[HUB_KEY] = HubInstance

-- ========== LOGO (embedded) ==========
local LOGO_ASSET = ""
pcall(function()
    local b64 = ""
    local raw
    if crypt and crypt.base64decode then
        raw = crypt.base64decode(b64)
    elseif base64 and base64.decode then
        raw = base64.decode(b64)
    else
        -- minimal base64 decode fallback
        local b = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
        local data, pad = b64:gsub("=", ""), #b64 - #b64:gsub("=", "")
        local t = {}
        for i = 1, #data, 4 do
            local n = (b:find(data:sub(i,i)) - 1) * 262144
                + ((b:find(data:sub(i+1,i+1)) or 1) - 1) * 4096
                + ((b:find(data:sub(i+2,i+2)) or 1) - 1) * 64
                + ((b:find(data:sub(i+3,i+3)) or 1) - 1)
            t[#t+1] = string.char(math.floor(n/65536)%256, math.floor(n/256)%256, n%256)
        end
        raw = table.concat(t):sub(1, #t*3 - pad)
    end
    if isfolder and not isfolder("PawZHub") then makefolder("PawZHub") end
    local path = "PawZHub/logo.png"
    if writefile then writefile(path, raw) end
    if getcustomasset then
        LOGO_ASSET = getcustomasset(path)
    end
end)

