local function GetFeatureHelp(title)
    -- title may be localized; map back via reverse lookup is hard — store help by English key on MakeToggle
    local pack = (Config.Language == "vi") and FeatureHelpVI or FeatureHelpEN
    return pack[title]
end

local UILangRefs = {} -- { {obj=, key=} or {obj=, getText=} }
local function BindLang(obj, key)
    if obj then UILangRefs[#UILangRefs + 1] = {obj = obj, key = key} end
    return obj
end

local function ApplyLanguage()
    for _, ref in ipairs(UILangRefs) do
        local o = ref.obj
        if o and o.Parent then
            if ref.key then
                pcall(function() o.Text = T(ref.key) end)
            elseif ref.fn then
                pcall(ref.fn)
            end
        end
    end
end


