local function encodeJSON(val)
    local t = typeof(val)
    if t == "nil" then return "null"
    elseif t == "boolean" then return val and "true" or "false"
    elseif t == "number" then return tostring(val)
    elseif t == "string" then return '"' .. val:gsub('\\','\\\\'):gsub('"','\\"'):gsub('\n','\\n') .. '"'
    elseif t == "table" then
        local isArr = #val > 0
        if isArr then
            local parts = {}
            for i,v in ipairs(val) do parts[i] = encodeJSON(v) end
            return "[" .. table.concat(parts, ",") .. "]"
        else
            local parts = {}
            for k,v in pairs(val) do
                if type(k) == "string" then
                    parts[#parts+1] = encodeJSON(k) .. ":" .. encodeJSON(v)
                end
            end
            return "{" .. table.concat(parts, ",") .. "}"
        end
    end
    return "null"
end

local function decodeJSON(str)
    -- minimal decoder via loadstring for executor environments
    if not str or str == "" then return nil end
    local ok, res = pcall(function()
        if game and game.HttpService then
            return game:GetService("HttpService"):JSONDecode(str)
        end
        return nil
    end)
    if ok and res then return res end
    -- fallback: return nil
    return nil
end

function ConfigIO:Save()
    local data = {}
    for _, k in ipairs(CONFIG_KEYS) do
        data[k] = Config[k]
    end
    local body
    pcall(function()
        if game and game.HttpService then body = game:GetService("HttpService"):JSONEncode(data)
        end
    end)
    if not body then body = encodeJSON(data) end
    pcall(function()
        if isfolder and not isfolder("PawZHub") then makefolder("PawZHub") end
        if writefile then writefile(CONFIG_PATH, body) end
    end)
    Toast:Show(T("toast_saved"), "ok")
    return true
end

function ConfigIO:Load()
    local raw
    pcall(function()
        if readfile and isfile and isfile(CONFIG_PATH) then
            raw = readfile(CONFIG_PATH)
        end
    end)
    if not raw then
        Toast:Show(T("toast_no_cfg"), "warn")
        return false
    end
    local data = nil
    -- Try HttpService first (most reliable)
    pcall(function()
        data = game:GetService("HttpService"):JSONDecode(raw)
    end)
    -- Fallback to custom decoder
    if not data then
        data = decodeJSON(raw)
    end
    -- Last resort: minimal manual parse for flat key-value
    if not data and raw:sub(1,1) == '{' then
        pcall(function()
            data = {}
            for k, v in raw:gmatch('"([^"]+)"%s*:%s*([^",}]+)') do
                if v == 'true' then data[k] = true
                elseif v == 'false' then data[k] = false
                elseif tonumber(v) then data[k] = tonumber(v)
                else data[k] = v:match('^"(.*)"$') or v end
            end
        end)
        if data and next(data) == nil then data = nil end
    end
    if type(data) ~= "table" then
        Toast:Show(T("toast_cfg_fail"), "warn")
        return false
    end
    for _, k in ipairs(CONFIG_KEYS) do
        if data[k] ~= nil then
            Config[k] = data[k]
        end
    end
    -- re-apply runtime
    pcall(function()
        if Config.AntiAFK then AntiAFK:Start() else AntiAFK:Stop() end
        ApplyWalkSpeed()
        FeatureEngine:EnsureRunning()
        if ApplyTheme then ApplyTheme() end
        if ApplyUILayout then ApplyUILayout() end
        if ApplyLanguage then ApplyLanguage() end
    end)
    Toast:Show(T("toast_loaded"), "ok")
    return true
end

