function ServerHop:HttpGetJson(url)
    local req = request or http_request or (syn and syn.request)
    if req then
        local response = req({Url = url, Method = "GET"})
        if response and (response.Success or response.StatusCode == 200) then
            local body = response.Body or response.body
            if body then
                return HttpService:JSONDecode(body)
            end
        end
    end
    -- last resort
    local ok, data = pcall(function()
        return HttpService:JSONDecode(game:HttpGet(url))
    end)
    if ok then return data end
    return nil
end

function ServerHop:CollectLowPopServers()
    -- ONLY servers with playing <= MaxPlayers (default 1) and not current
    local maxP = Config.MaxPlayers or 1
    if maxP < 1 then maxP = 1 end
    local currentJobId = game.JobId
    local candidates = {} -- {id, playing}
    local cursor = ""
    local pages = 0
    local maxPages = 8 -- scan up to 800 servers

    while pages < maxPages do
        pages = pages + 1
        local url = string.format(
            "https://games.roblox.com/v1/games/%s/servers/Public?sortOrder=Asc&limit=100%s",
            game.PlaceId,
            cursor ~= "" and ("&cursor=" .. cursor) or ""
        )
        local data = self:HttpGetJson(url)
        if not data or type(data) ~= "table" or not data.data then
            break
        end
        for _, server in ipairs(data.data) do
            local playing = tonumber(server.playing) or 99
            local id = server.id
            if id and id ~= currentJobId and playing <= maxP then
                table.insert(candidates, {id = id, playing = playing})
            end
        end
        -- prefer early exit if we already have empty (0) servers
        for _, c in ipairs(candidates) do
            if c.playing == 0 then
                return candidates
            end
        end
        cursor = data.nextPageCursor
        if not cursor or cursor == "" then break end
        task.wait(0.15)
    end
    return candidates
end

function ServerHop:PickBestServer(candidates)
    if not candidates or #candidates == 0 then return nil end
    -- Prefer fewest players: 0 first, then 1
    table.sort(candidates, function(a, b)
        return a.playing < b.playing
    end)
    return candidates[1]
end

function ServerHop:FindEmptyServer()
    if self.Checking then return end
    self.Checking = true

    self:ShowNotification("Searching servers ≤1 player...", Theme.accent2)

    local ok, candidates = pcall(function()
        return self:CollectLowPopServers()
    end)

    if not ok or not candidates then
        self:ShowNotification("Failed to fetch servers", Theme.danger)
        self.Checking = false
        return
    end

    local best = self:PickBestServer(candidates)
    self.Checking = false

    if best then
        self:ShowNotification(
            string.format("Found: %d player(s) — joining...", best.playing),
            Theme.success
        )
        task.wait(0.6)
        local tpOk, tpErr = pcall(function()
            TeleportService:TeleportToPlaceInstance(game.PlaceId, best.id, Player)
        end)
        if not tpOk then
            self:ShowNotification("Teleport failed: " .. tostring(tpErr), Theme.danger)
        end
    else
        -- NEVER random hop (would land on full servers)
        self:ShowNotification("No server with ≤1 player found. Retry later.", Theme.danger)
    end
end

function ServerHop:QuickHop()
    -- Same strict rule: only ≤ MaxPlayers
    self:FindEmptyServer()
end

function ServerHop:Start()
    if self.Active then return end
    self.Active = true
    
    spawn(function()
        while self.Active and Config.AutoServerHop do
            local now = tick()
            if now - self.LastCheck >= self.CheckInterval then
                self.LastCheck = now
                
                local currentPlayers = #Players:GetPlayers()
                if currentPlayers > Config.MaxPlayers then
                    self:ShowNotification(
                        string.format("Server has %d players, searching...", currentPlayers),
                        Theme.accent2
                    )
                    self:FindEmptyServer()
                end
            end
            task.wait(1)
        end
    end)
end

function ServerHop:Stop()
    self.Active = false
end

function ServerHop:Toggle()
    Config.AutoServerHop = not Config.AutoServerHop
    if Config.AutoServerHop then
        self:Start()
        if #Players:GetPlayers() > (Config.MaxPlayers or 1) then
            task.spawn(function()
                self:FindEmptyServer()
            end)
        end
    else
        self:Stop()
    end
end

