-- ========== OPTIMIZED FEATURE ENGINE ==========
-- Single shared loop + cached prompts to avoid lag

local FeatureEngine = {
    Running = false,
    Connection = nil,
    PromptCache = {},
    LastCacheRefresh = 0,
    CacheInterval = 5.5, -- full prompt rescan (higher = less lag)
    LastBuy = 0,
    LastPlant = 0,
    LastHarvest = 0,
    LastCollect = 0,
    LastSell = 0,
    BuyCount = 0,
    PlantCount = 0,
    HarvestCount = 0,
    CollectCount = 0,
    SellCount = 0,
    Busy = false,
    RecentBuys = {},
    RecentActions = {},
    FailStreak = 0,
    LastTick = 0,
    LastActionAt = 0,
    TickInterval = 0.35, -- base throttle (raised for less lag)
    MoneyCache = nil,
    MoneyCacheAt = 0,
    _watchInit = false,
    FertBusy = false,
    Phase = 0,
}

local RARITY_WEIGHT = {
    void = 100, diamond = 95, pizza = 90, magic = 85,
    blooming = 80, glowing = 75,
    dragon = 70, starfruit = 65, banana = 60,
    coconut = 55, mango = 50, cherry = 45,
    avocado = 40, lemon = 35, orange = 30,
    fig = 25, peach = 20, apple = 15,
    pine = 10, oak = 5,
}

function FeatureEngine:RefreshCache()
    -- Prune dead refs; full rescan only when empty/stale
    local alive = {}
    for _, p in ipairs(self.PromptCache) do
        if p and p.Parent and p:IsA("ProximityPrompt") then
            alive[#alive + 1] = p
        end
    end
    self.PromptCache = alive
    if #alive > 0 and (tick() - (self.LastCacheRefresh or 0)) < (self.CacheInterval or 5.5) then
        self.LastCacheRefresh = tick()
        return
    end

    local list = {}
    local seen = {}
    local hrp = Player.Character and Player.Character:FindFirstChild("HumanoidRootPart")
    local origin = hrp and hrp.Position
    local maxDist = math.max((Config.FarmRange or 60) * 2.2, 120)
    if Config.AutoBuy then
        maxDist = math.max(maxDist, 250) -- buy may be farther (conveyor)
    end

    -- Prefer named containers (avoid double-scan of entire workspace when possible)
    local roots = {}
    pcall(function()
        for _, name in ipairs({"Plots", "Plot", "Farms", "Market", "Map", "World", "Game", "Seeds", "Conveyor", "Tycoons", "Tycoon"}) do
            local f = workspace:FindFirstChild(name)
            if f then roots[#roots + 1] = f end
        end
    end)
    if #roots == 0 then
        roots[1] = workspace
    else
        -- still include workspace only if few named roots
        if #roots < 2 then roots[#roots + 1] = workspace end
    end

    for _, root in ipairs(roots) do
        for _, obj in ipairs(root:GetDescendants()) do
            if obj:IsA("ProximityPrompt") and obj.Enabled and not seen[obj] then
                seen[obj] = true
                if origin then
                    local part = obj.Parent
                    if part and part:IsA("BasePart") then
                        if (part.Position - origin).Magnitude <= maxDist then
                            list[#list + 1] = obj
                        end
                    else
                        list[#list + 1] = obj
                    end
                else
                    list[#list + 1] = obj
                end
                if #list >= 220 then break end
            end
        end
        if #list >= 220 then break end
    end
    self.PromptCache = list
    self.LastCacheRefresh = tick()
end

-- Live prompt tracking (smarter than pure interval cache)
if not FeatureEngine._hooked then
    FeatureEngine._hooked = true
    pcall(function()
        workspace.DescendantAdded:Connect(function(obj)
            if obj:IsA("ProximityPrompt") then
                table.insert(FeatureEngine.PromptCache, obj)
            end
        end)
        workspace.DescendantRemoving:Connect(function(obj)
            if obj:IsA("ProximityPrompt") then
                for i = #FeatureEngine.PromptCache, 1, -1 do
                    if FeatureEngine.PromptCache[i] == obj then
                        table.remove(FeatureEngine.PromptCache, i)
                    end
                end
            end
        end)
    end)
end


function FeatureEngine:TextOf(prompt)
    local a = (prompt.ActionText or ""):lower()
    local o = (prompt.ObjectText or ""):lower()
    local n = (prompt.Name or ""):lower()
    local pn = ""
    local ppn = ""
    pcall(function()
        if prompt.Parent then pn = (prompt.Parent.Name or ""):lower()
            if prompt.Parent.Parent then
                ppn = (prompt.Parent.Parent.Name or ""):lower()
            end
        end
    end)
    return a, o, a .. " " .. o .. " " .. n .. " " .. pn .. " " .. ppn
end

-- True if prompt lives under market / conveyor (not home plot free stands / Give Seed)
function FeatureEngine:IsConveyorSeed(prompt)
    local action, object, text = self:TextOf(prompt)
    if text:find("give seed") or (text:find("give") and text:find("seed")) then return false end
    if text:find("plant seed") or text:find("harvest") or text:find("sell") then return false end
    local inst = prompt
    local sawMarket, sawHome = false, false
    for _ = 1, 14 do
        if not inst or inst == game then break end
        local n = (inst.Name or ""):lower()
        if n:find("conveyor", 1, true) or n:find("belt", 1, true) or n:find("market", 1, true)
            or n:find("seedbelt", 1, true) or n:find("seedspawn", 1, true) or n:find("dropper", 1, true)
            or n:find("restock", 1, true) or n:find("stock", 1, true) or n:find("track", 1, true)
            or n:find("river", 1, true) or n:find("stream", 1, true)
            or (n:find("pad", 1, true) and (n:find("seed") or n:find("buy")))
            or n:find("shop", 1, true) or n:find("seller", 1, true) or n:find("vendor", 1, true) then
            sawMarket = true
        end
        if n:find("plot", 1, true) or n:find("garden", 1, true) or n:find("homebase", 1, true)
            or n:find("playerplot", 1, true) or n:find("farmplot", 1, true) or n:find("claim", 1, true)
            or n:find("backpack", 1, true) or n:find("inventory", 1, true)
            or n:find("basket", 1, true) or n:find("storage", 1, true) or n:find("giveseed", 1, true) then
            sawHome = true
        end
        inst = inst.Parent
    end
    if sawHome and not sawMarket then return false end
    if sawMarket then return true end
    local part = self:GetPromptPart(prompt)
    if part then
        local pn = (part.Name or ""):lower()
        if pn:find("conveyor") or pn:find("belt") or pn:find("market") then return true end
        -- Moving parts = belt seeds (home stands are static)
        local ok, speed = pcall(function()
            return part.AssemblyLinearVelocity.Magnitude
        end)
        if ok and speed and speed > 0.35 then return true end
        -- Also check primary part of model
        local model = part:FindFirstAncestorOfClass("Model")
        if model then
            local pp = model.PrimaryPart or model:FindFirstChildWhichIsA("BasePart")
            if pp then
                local ok2, sp2 = pcall(function() return pp.AssemblyLinearVelocity.Magnitude end)
                if ok2 and sp2 and sp2 > 0.35 then return true end
            end
        end
    end
    return false
end

function FeatureEngine:IsWantedSeed(prompt)
    local action, object, text = self:TextOf(prompt)
    -- Greedy Growers: never buy from Give Seed basket / plot / storage
    if text:find("give seed") or (text:find("give") and text:find("seed")) then return false end
    if text:find("plant seed") or text:find("plant") then return false end
    if text:find("deposit") or text:find("storage") or text:find("basket") then return false end
    -- Never claim / plant / harvest / sell
    if action:find("claim") or action:find("plant") or action:find("harvest")
        or action:find("sell") or action:find("collect") or action:find("water")
        or action:find("give") then
        return false
    end
    local isBuy = action:find("buy") ~= nil or text:find("buy") ~= nil or text:find("purchase") ~= nil
    local isSeed = object:find("seed") ~= nil or text:find("seed") ~= nil
    if not isSeed then return false end
    -- Prefer explicit buy; allow seed object with Hold/Interact if on conveyor
    if not isBuy and not (Config.BuyConveyorOnly and self:IsConveyorSeed(prompt)) then
        return false
    end
    -- Conveyor / market only (skip home free seed stands)
    if Config.BuyConveyorOnly ~= false then
        if not self:IsConveyorSeed(prompt) then
            return false
        end
    end
    if Config.BuySkipSoldOut then
        if text:find("sold out") or text:find("out of stock") or text:find("unavailable")
            or text:find("not enough") or text:find("can't buy") or text:find("cannot buy") then
            return false
        end
    end
    if Config.BuyFreeOnly then
        if not (object:find("free") or action:find("free") or text:find("free") or text:find("$0") or text:find("0$")) then
            return false
        end
    end
    if (Config.MinRarity or 0) > 0 then
        local rank = 0
        for key, r in pairs(RARITY_RANK) do
            if object:find(key) or text:find(key) then
                if r > rank then rank = r end
            end
        end
        if rank < Config.MinRarity then return false end
    end
    local maxd = Config.BuyRange or 9999
    if maxd < 9000 and self:DistanceTo(prompt) > maxd then return false end
    -- Skip if we can read price and player cannot afford
    if not self:CanAfford(prompt) then return false end

    if Config.BuyAll then return true end
    for seedName, enabled in pairs(Config.SelectedSeeds or {}) do
        if enabled then
            local sn = seedName:lower()
            local short = sn:gsub(" seed", "")
            if object:find(sn, 1, true) or text:find(sn, 1, true)
                or object:find(short, 1, true) or text:find(short, 1, true) then
                return true
            end
        end
    end
    return false
end

function FeatureEngine:SeedPriority(prompt)
    local _, object, text = self:TextOf(prompt)
    local best = 0
    for key, w in pairs(RARITY_WEIGHT) do
        if object:find(key) or text:find(key) then
            if w > best then best = w end
        end
    end
    -- free boost when prefer free
    if Config.BuyPreferFree and (text:find("free") or text:find("$0")) then
        best = best + 50
    end
    return best
end

function FeatureEngine:SortBuyList(list)
    local mode = Config.BuySortMode or "smart"
    if mode == "nearest" then
        table.sort(list, function(a, b) return self:DistanceTo(a) < self:DistanceTo(b) end)
    elseif mode == "balanced" then
        -- rarity weight / (distance + 1)
        table.sort(list, function(a, b)
            local sa = self:SeedPriority(a) / (self:DistanceTo(a) + 1)
            local sb = self:SeedPriority(b) / (self:DistanceTo(b) + 1)
            return sa > sb
        end)
    else -- smart = rarity first, then distance
        table.sort(list, function(a, b)
            local pa, pb = self:SeedPriority(a), self:SeedPriority(b)
            if pa == pb then return self:DistanceTo(a) < self:DistanceTo(b) end
            return pa > pb
        end)
    end
end

function FeatureEngine:GetPromptPart(prompt)
    local inst = prompt.Parent
    while inst and inst ~= workspace do
        if inst:IsA("BasePart") then return inst end
        if inst:IsA("Model") then
            local p = inst.PrimaryPart or inst:FindFirstChildWhichIsA("BasePart")
            if p then return p end
        end
        inst = inst.Parent
    end
    return nil
end

function FeatureEngine:DistanceTo(prompt)
    local hrp = Player.Character and Player.Character:FindFirstChild("HumanoidRootPart")
    local part = self:GetPromptPart(prompt)
    if not hrp or not part then return 9999 end
    return (hrp.Position - part.Position).Magnitude
end

function FeatureEngine:Fire(prompt)
    if not prompt or not prompt.Parent then return false end
    local ok = false
    pcall(function()
        pcall(function()
            prompt.MaxActivationDistance = 1e9
            prompt.RequiresLineOfSight = false
            prompt.HoldDuration = 0
            prompt.Enabled = true
        end)
        -- Try all methods (some games only accept one)
        if fireproximityprompt then
            local a = pcall(fireproximityprompt, prompt)
            local b = pcall(fireproximityprompt, prompt, 1)
            ok = ok or a or b
        end
        pcall(function()
            prompt:InputHoldBegin()
            task.wait(0.03)
            prompt:InputHoldEnd()
            ok = true
        end)
        if firesignal then
            pcall(function() firesignal(prompt.Triggered, Players.LocalPlayer) end)
            pcall(function() firesignal(prompt.PromptButtonHoldBegan, Players.LocalPlayer) end)
            ok = true
        end
        if getconnections then
            for _, sigName in ipairs({"Triggered", "PromptButtonHoldBegan", "TriggerEnded"}) do
                local sOk, signal = pcall(function() return prompt[sigName] end)
                if sOk and signal then
                    for _, conn in ipairs(getconnections(signal)) do
                        pcall(function()
                            if conn.Fire then conn:Fire(Players.LocalPlayer)
                            elseif conn.Function then conn.Function(Players.LocalPlayer) end
                        end)
                    end
                    ok = true
                end
            end
        end
    end)
    return ok
end

-- forceTP = true for farm (ignore BuyTeleport flag)
function FeatureEngine:FireNear(prompt, maxDist, forceTP)
    maxDist = maxDist or 18
    local hrp = Player.Character and Player.Character:FindFirstChild("HumanoidRootPart")
    local part = self:GetPromptPart(prompt)
    if not hrp or not part then
        return self:Fire(prompt)
    end
    local dist = (hrp.Position - part.Position).Magnitude
    local allowTP = forceTP or (Config.FarmTeleport ~= false) or (Config.BuyTeleport ~= false)
    if dist <= maxDist or not allowTP then
        return self:Fire(prompt)
    end
    if self.Busy then
        return self:Fire(prompt)
    end
    self.Busy = true
    local fired = false
    pcall(function()
        local oldCF = hrp.CFrame
        hrp.CFrame = CFrame.new(part.Position + Vector3.new(0, 3, 0))
        task.wait(0.1)
        fired = self:Fire(prompt)
        task.wait(0.08)
        if hrp and hrp.Parent then hrp.CFrame = oldCF end
    end)
    self.Busy = false
    return fired
end

-- Parse abbreviated money: 12.87Sp, 1.2K, 350, $1.5M ...
function FeatureEngine:ParseNumber(str)
    if not str or str == "" then return nil end
    str = tostring(str):gsub(",", ""):gsub("%$", ""):gsub("%s", "")
    local num, suf = str:match("^([%d%.]+)([%a]*)$")
    if not num then return nil end
    local n = tonumber(num)
    if not n then return nil end
    suf = (suf or ""):lower()
    local mult = 1
    if suf == "k" then mult = 1e3
    elseif suf == "m" then mult = 1e6
    elseif suf == "b" then mult = 1e9
    elseif suf == "t" then mult = 1e12
    elseif suf == "qa" or suf == "q" then mult = 1e15
    elseif suf == "qi" then mult = 1e18
    elseif suf == "sx" or suf == "s" then mult = 1e21
    elseif suf == "sp" then mult = 1e24
    elseif suf == "oc" or suf == "o" then mult = 1e27
    elseif suf == "no" or suf == "n" then mult = 1e30
    elseif suf == "dc" then mult = 1e33
    end
    return n * mult
end

function FeatureEngine:GetPlayerMoney()
    local now = tick()
    if self.MoneyCache ~= nil and (now - (self.MoneyCacheAt or 0)) < 0.6 then
        return self.MoneyCache
    end
    local best = nil
    pcall(function()
        local ls = Player:FindFirstChild("leaderstats")
        if ls then
            for _, v in ipairs(ls:GetChildren()) do
                if v:IsA("NumberValue") or v:IsA("IntValue") or v:IsA("StringValue") then
                    local nm = (v.Name or ""):lower()
                    if nm:find("money") or nm:find("cash") or nm:find("coin") or nm:find("gold") or nm == "$" then
                        local n = tonumber(v.Value) or self:ParseNumber(tostring(v.Value))
                        if n and (not best or n > best) then best = n end
                    end
                end
            end
        end
    end)
    -- GUI fallback only if leaderstats missing (expensive)
    if best == nil then
        pcall(function()
            local pg = Player:FindFirstChild("PlayerGui")
            if not pg then return end
            for _, gui in ipairs(pg:GetDescendants()) do
                if gui:IsA("TextLabel") then
                    local t = gui.Text or ""
                    if #t < 24 and t:find("%$") then
                        local m = t:match("%$%s*([%d%.,]+%a*)")
                        local n = self:ParseNumber(m)
                        if n and n > 0 and (not best or n > best) then best = n end
                    end
                end
            end
        end)
    end
    self.MoneyCache = best
    self.MoneyCacheAt = now
    return best
end

function FeatureEngine:GetSeedPrice(prompt)
    local _, _, text = self:TextOf(prompt)
    -- FREE
    if text:find("free") or text:find("$0") then return 0 end
    -- Nearby billboard / labels
    local candidates = { text }
    local part = self:GetPromptPart(prompt)
    local root = prompt.Parent
    if root then
        for _, gui in ipairs(root:GetDescendants()) do
            if gui:IsA("TextLabel") or gui:IsA("TextButton") then
                candidates[#candidates + 1] = (gui.Text or ""):lower()
            end
        end
    end
    if part then
        for _, gui in ipairs(part:GetDescendants()) do
            if gui:IsA("TextLabel") or gui:IsA("TextButton") then
                candidates[#candidates + 1] = (gui.Text or ""):lower()
            end
        end
        -- sibling billboards
        pcall(function()
            for _, bb in ipairs(part:GetChildren()) do
                if bb:IsA("BillboardGui") or bb:IsA("SurfaceGui") then
                    for _, gui in ipairs(bb:GetDescendants()) do
                        if gui:IsA("TextLabel") or gui:IsA("TextButton") then
                            candidates[#candidates + 1] = (gui.Text or ""):lower()
                        end
                    end
                end
            end
        end)
    end
    local price = nil
    for _, t in ipairs(candidates) do
        if t:find("free") then return 0 end
        -- $350 or 350$ or price: 1.2k
        for raw in t:gmatch("%$%s*([%d%.,]+%a*)") do
            local n = self:ParseNumber(raw)
            if n and n > 0 then price = price and math.min(price, n) or n end
        end
        for raw in t:gmatch("([%d%.,]+%a*)%s*%$") do
            local n = self:ParseNumber(raw)
            if n and n > 0 then price = price and math.min(price, n) or n end
        end
    end
    return price -- nil = unknown
end

function FeatureEngine:CanAfford(prompt)
    local price = self:GetSeedPrice(prompt)
    if price == nil then return true end -- unknown: allow
    if price <= 0 then return true end -- free
    local money = self:GetPlayerMoney()
    if money == nil then return true end -- can't read money: allow
    return money + 0.0001 >= price
end

function FeatureEngine:CleanSeedName(raw)
    local s = tostring(raw or ""):lower()
    s = s:gsub("\n", " "):gsub("%s+", " ")
    s = s:gsub("^buy%s+", ""):gsub("^purchase%s+", ""):gsub("^claim%s+", "")
    s = s:gsub("%s+buy$", "")
    s = s:gsub("seed", "seed")
    -- title case short
    s = s:gsub("(%a)([%w_']*)", function(a, b) return a:upper() .. b end)
    if #s > 18 then s = s:sub(1, 18) .. "…" end
    return s
end

function FeatureEngine:FireBuy(prompt)
    local now = tick()
    if not self:CanAfford(prompt) then return false end

    local _, _, rawName = self:TextOf(prompt)
    local key = (rawName or "") .. tostring(self:GetPromptPart(prompt) and self:GetPromptPart(prompt).Position or "")
    key = key:lower()
    self.RecentBuys = self.RecentBuys or {}
    -- Global buy cooldown (anti-lag spam)
    if self.LastBuyFire and now - self.LastBuyFire < 0.35 then return false end
    if self.RecentBuys[key] and now - self.RecentBuys[key] < 1.4 then return false end
    self.RecentBuys[key] = now
    self.LastBuyFire = now

    local dist = self:DistanceTo(prompt)
    self:Fire(prompt)

    if dist > 16 and Config.BuyTeleport ~= false then
        if self.Busy then return true end
        local hrp = Player.Character and Player.Character:FindFirstChild("HumanoidRootPart")
        local part = self:GetPromptPart(prompt)
        if hrp and part then
            self.Busy = true
            pcall(function()
                local oldCF = hrp.CFrame
                hrp.CFrame = CFrame.new(part.Position + Vector3.new(0, 3, 0))
                task.wait(0.08)
                self:Fire(prompt)
                task.wait(0.06)
                if hrp and hrp.Parent then
                    hrp.CFrame = oldCF
                end
            end)
            self.Busy = false
        end
    end
    return true
end

function FeatureEngine:GetMultiplier(prompt)
    -- Local only — never scan whole workspace (major lag source)
    local best = nil
    local function scan(t)
        if not t then return end
        local n = tonumber(t:match("([%d%.]+)x")) or tonumber(t:match("x([%d%.]+)"))
        if n and (not best or n > best) then best = n end
    end
    local _, _, text = self:TextOf(prompt)
    scan(text)
    local parent = prompt.Parent
    if parent then
        for _, gui in ipairs(parent:GetChildren()) do
            if gui:IsA("TextLabel") or gui:IsA("TextButton") or gui:IsA("BillboardGui") then
                if gui:IsA("BillboardGui") then
                    for _, c in ipairs(gui:GetDescendants()) do
                        if c:IsA("TextLabel") then scan(c.Text or "") end
                    end
                else
                    scan(gui.Text or "")
                end
            end
        end
        -- one level of descendants only
        for _, gui in ipairs(parent:GetDescendants()) do
            if gui:IsA("TextLabel") then
                scan(gui.Text or "")
                if best and best >= 20 then break end
            end
        end
    end
    return best
end

function FeatureEngine:IsPlantPrompt(prompt)
    local action, object, text = self:TextOf(prompt)
    -- Greedy Growers: only "Plant Seed" on plot — never Give Seed basket
    if text:find("give seed") or (text:find("give") and text:find("seed")) then return false end
    if text:find("deposit") or text:find("storage") or text:find("basket") then return false end
    if action:find("buy") or action:find("sell") or action:find("harvest") or action:find("claim") or action:find("give") then return false end
    if text:find("buy seed") or text:find("purchase") or text:find("sell") or text:find("harvest") then return false end
    if text:find("fertiliz") or text:find("fertiliser") or text:find("select fertilizer") then return false end
    if text:find("feed") or text:find("pick up") or text:find("view") then return false end
    -- Greedy Growers primary
    if text:find("plant seed") then return true end
    if action:find("plant") and (text:find("seed") or object:find("seed") or object:find("plot")) then return true end
    if text:find("empty") and (text:find("plot") or text:find("soil") or text:find("dirt") or text:find("pad")) then return true end
    return false
end

function FeatureEngine:IsHarvestPrompt(prompt)
    local action, object, text = self:TextOf(prompt)
    -- Never seed basket / plant / buy / sell
    if text:find("give seed") or (text:find("give") and text:find("seed")) then return false end
    if text:find("plant seed") or text:find("buy") or text:find("sell") then return false end
    if text:find("feed") or text:find("pick up") then return false end
    if action:find("buy") or action:find("plant") or action:find("sell") or action:find("give") then return false end
    if text:find("fertiliz") or text:find("select fertilizer") then return false end
    if action:find("harvest") or object:find("harvest") or text:find("harvest") then return true end
    if text:find("%d+%.?%d*x") and not text:find("seed") and not text:find("ticket") then return true end
    return false
end

function FeatureEngine:IsCollectPrompt(prompt)
    local action, object, text = self:TextOf(prompt)
    if text:find("give seed") or (text:find("give") and text:find("seed")) then return false end
    if text:find("plant seed") or text:find("buy") or text:find("sell") then return false end
    if text:find("feed") or text:find("pick up") or text:find("view") then return false end
    if action:find("buy") or action:find("plant") or action:find("sell") or action:find("harvest") or action:find("give") then return false end
    if text:find("harvest") or text:find("fertiliz") then return false end
    if Config.CollectFruits ~= false then
        if action:find("pick") or action:find("grab") or action:find("take") then return true end
        if text:find("collect fruit") or text:find("pickup fruit") or text:find("pick up fruit") then return true end
        if text:find("fruit") and (action:find("collect") or action:find("interact") or action:find("pick")) then return true end
        if text:find("fruit") and not text:find("seed") and not text:find("buy") and not text:find("submit") then return true end
    end
    if Config.CollectDead ~= false then
        if text:find("dead") or text:find("wilt") or text:find("rot") or text:find("clear")
            or text:find("remove") or text:find("chop") or text:find("clean") or text:find("destroy") then
            return true
        end
    end
    if action:find("collect") and not text:find("seed") and not text:find("give") then return true end
    return false
end

function FeatureEngine:IsSellPrompt(prompt)
    local action, object, text = self:TextOf(prompt)
    if text:find("give seed") or (text:find("give") and text:find("seed")) then return false end
    if text:find("plant seed") or text:find("harvest") or text:find("fertiliz") then return false end
    if action:find("buy") or action:find("plant") or action:find("harvest") or action:find("give") then return false end
    if action:find("sell") or object:find("sell") or text:find("sell") then
        -- Allow sell fruit / sell all; block ambiguous seed-only labels without sell action
        if text:find("seed") and not action:find("sell") and not text:find("sell") then return false end
        return true
    end
    return false
end

function FeatureEngine:SortByDistance(list)
    local dist = {}
    for _, p in ipairs(list) do
        dist[p] = self:DistanceTo(p)
    end
    table.sort(list, function(a, b) return dist[a] < dist[b] end)
    return dist
end

-- True if prompt belongs to local player's plot (blocks TP into other gardens)
function FeatureEngine:IsOwnPlot(prompt)
    if Config.OwnPlotOnly == false then return true end
    if not prompt or not prompt.Parent then return false end
    local myName = (Player.Name or ""):lower()
    local myId = tostring(Player.UserId or "")
    local display = (Player.DisplayName or ""):lower()
    local node = prompt
    local sawPlot = false
    for _ = 1, 16 do
        if not node or node == game then break end
        local n = (node.Name or ""):lower()
        if n:find("plot", 1, true) or n:find("garden", 1, true) or n:find("farm", 1, true) then sawPlot = true
        end
        if n == myName or n == myId or (display ~= "" and n == display) then
            return true
        end
        if myName ~= "" and n:find(myName, 1, true) then return true end
        if myId ~= "" and n:find(myId, 1, true) then return true end
        local okAttr, owner = pcall(function()
            return node:GetAttribute("Owner") or node:GetAttribute("OwnerName")
                or node:GetAttribute("OwnerId") or node:GetAttribute("Player")
                or node:GetAttribute("UserId") or node:GetAttribute("UserID")
        end)
        if okAttr and owner ~= nil then
            local s = tostring(owner):lower()
            if s == myName or s == myId or s == display then return true end
            -- owned by someone else
            if sawPlot and s ~= "" and s ~= myName and s ~= myId then
                return false
            end
        end
        -- ObjectValue / StringValue owner refs
        pcall(function()
            local ov = node:FindFirstChild("Owner") or node:FindFirstChild("Player")
            if ov then
                if ov:IsA("ObjectValue") and ov.Value == Player then
                    sawPlot = true
                    -- mark owned
                    node = nil
                elseif ov:IsA("StringValue") then
                    local s = (ov.Value or ""):lower()
                    if s == myName or s == myId then node = nil end
                end
            end
        end)
        if node == nil then return true end
        node = node.Parent
    end
    -- Standing on it (own plot gameplay)
    local d = self:DistanceTo(prompt)
    if d <= 32 then return true end
    return false
end

-- opts.skipOwnCheck = true for sell / shop prompts not on plot
function FeatureEngine:FireFarm(prompt, maxRange, opts)
    opts = opts or {}
    maxRange = maxRange or Config.FarmRange or 120
    if not opts.skipOwnCheck and not self:IsOwnPlot(prompt) then
        return false
    end
    local d = self:DistanceTo(prompt)
    self:Fire(prompt)
    if d <= 22 then
        return true
    end
    if (Config.FarmTeleport ~= false) and d <= maxRange then
        self:FireNear(prompt, 12, true)
        return true
    end
    return d <= maxRange
end

function FeatureEngine:ShouldHarvest(prompt)
    if Config.HarvestOnlyGrown == false then return true end
    local mult = self:GetMultiplier(prompt)
    local need = Config.HarvestMultiplier or 2
    if mult then
        return mult + 0.001 >= need
    end
    -- unknown mult: still harvest (most reliable for this game)
    return true
end

function FeatureEngine:SafetyBlocked()
    if not Config.SafetyEnabled then return false end
    if self.FailStreak >= (Config.MaxPromptFails or 8) then
        Toast:Show(T("toast_safety"), "warn")
        Config.AutoBuy = false
        Config.AutoPlant = false
        Config.AutoHarvest = false
        Config.AutoCollect = false
        Config.AutoSell = false
        Config.AutoFertilizer = false
        Config.AutoRebirth = false
        Config.AutoFeedPet = false
        self.FailStreak = 0
        self:EnsureRunning()
        return true
    end
    return false
end

function FeatureEngine:NoteFail()
    self.FailStreak = (self.FailStreak or 0) + 1
end

function FeatureEngine:NoteSuccess()
    self.FailStreak = 0
    self.LastActionAt = tick()
end

function FeatureEngine:WithinRange(prompt)
    local d = self:DistanceTo(prompt)
    local maxd = Config.MaxPromptDistance or 80
    return d <= maxd
end

function FeatureEngine:Tick()
    local now = tick()
    if self:SafetyBlocked() then return end

    -- Idle throttle: slow cache when nothing enabled recently
    local any = Config.AutoBuy or Config.AutoPlant or Config.AutoHarvest or Config.AutoCollect
        or Config.AutoSell or Config.AutoRebirth or Config.AutoFertilizer
        or Config.AutoPlaceEgg or Config.AutoEquipPet or Config.AutoFeedPet
    if not any then return end

    local cacheIv = self.CacheInterval
    if Config.IdleThrottle and (now - (self.LastActionAt or 0)) > 8 then
        cacheIv = 4.0
    end
    if now - self.LastCacheRefresh >= cacheIv or #self.PromptCache == 0 then
        self:RefreshCache()
    end

    -- Stagger work across ticks so 1 frame never does everything
    self.Phase = (self.Phase or 0) + 1
    local phase = self.Phase
    local perf = Config.PerformanceMode ~= false
    local hIv = Config.HarvestInterval or (perf and 0.55 or 0.4)
    local cIv = Config.CollectInterval or (perf and 0.55 or 0.4)
    local pIv = Config.PlantInterval or (perf and 0.6 or 0.45)
    local bIv = Config.BuyInterval or (perf and 0.5 or 0.35)
    local sIv = Config.SellInterval or (perf and 1.6 or 1.2)
    local needHarvest = Config.AutoHarvest and (now - self.LastHarvest >= hIv) and (not perf or phase % 2 == 0)
    local needCollect = Config.AutoCollect and (now - self.LastCollect >= cIv) and (not perf or phase % 2 == 1)
    local needPlant = Config.AutoPlant and (now - self.LastPlant >= pIv) and (not perf or phase % 3 == 0)
    local needBuy = Config.AutoBuy and (now - self.LastBuy >= bIv) and (not perf or phase % 3 == 1)
    local needSell = Config.AutoSell and (now - self.LastSell >= sIv) and (not perf or phase % 4 == 0)
    local needFert = Config.AutoFertilizer and (now - (self.LastFert or 0) >= 1.4) and not self.FertBusy

    local farmRange = Config.FarmRange or 60
    local alive = {}
    local buyList, plantList, harvestList, collectList, sellList, fertList = {}, {}, {}, {}, {}, {}

    for _, prompt in ipairs(self.PromptCache) do
        if prompt and prompt.Parent and prompt:IsA("ProximityPrompt") and prompt.Enabled then
            alive[#alive + 1] = prompt
            if needBuy and self:IsWantedSeed(prompt) then
                buyList[#buyList + 1] = prompt
            else
                local d = self:DistanceTo(prompt)
                if d <= farmRange then
                    if needHarvest and self:IsHarvestPrompt(prompt) then
                        harvestList[#harvestList + 1] = prompt
                    elseif needPlant and self:IsPlantPrompt(prompt) then
                        plantList[#plantList + 1] = prompt
                    elseif needCollect and self:IsCollectPrompt(prompt) then
                        collectList[#collectList + 1] = prompt
                    elseif needSell and self:IsSellPrompt(prompt) then
                        sellList[#sellList + 1] = prompt
                    elseif needFert and self:IsFertilizerPrompt(prompt) then
                        fertList[#fertList + 1] = prompt
                    end
                end
            end
        end
    end
    self.PromptCache = alive

    -- FARM PIPELINE (same tick can do multiple farm jobs)
    local farmWorked = false

    -- 1) HARVEST ready crops (highest priority)
    if needHarvest then
        if #harvestList > 0 then
            self:SortByDistance(harvestList)
            local limit = math.clamp(Config.HarvestPerCycle or 3, 1, 8)
            if perf then limit = math.min(limit, 3) end
            local n = 0
            for _, p in ipairs(harvestList) do
                if n >= limit then break end
                if self:ShouldHarvest(p) then
                    if self:FireFarm(p, farmRange) then
                        n = n + 1
                        self.HarvestCount = (self.HarvestCount or 0) + 1
                        farmWorked = true
                    end
                end
            end
            if n > 0 then
                self:NoteSuccess()
                if self.HarvestCount % 8 == 0 then
                    Toast:Show("Harvested ×" .. tostring(self.HarvestCount), "ok")
                end
            end
        end
        self.LastHarvest = now
    end

    -- 2) COLLECT fruits / dead trees
    if needCollect then
        if #collectList > 0 then
            self:SortByDistance(collectList)
            local limit = math.clamp(Config.CollectPerCycle or 4, 1, 10)
            if perf then limit = math.min(limit, 4) end
            local n = 0
            for _, p in ipairs(collectList) do
                if n >= limit then break end
                if self:FireFarm(p, farmRange) then
                    n = n + 1
                    self.CollectCount = (self.CollectCount or 0) + 1
                    farmWorked = true
                end
            end
            if n > 0 then self:NoteSuccess() end
        end
        self.LastCollect = now
    end

    -- 3) PLANT empty plots (Greedy Growers: Plant Seed → SELECT FERTILIZER GUI)
    if needPlant then
        if #plantList > 0 then
            self:SortByDistance(plantList)
            -- 1 plant/cycle when fertilizer ON (panel can only handle one at a time)
            local limit = math.clamp(Config.PlantPerCycle or 2, 1, 6)
            if Config.AutoFertilizer then limit = 1 end
            if perf then limit = math.min(limit, 2) end
            local range = Config.PlantRange or farmRange
            local n = 0
            for _, p in ipairs(plantList) do
                if n >= limit then break end
                local _, _, ptx = self:TextOf(p)
                if ptx:find("give") or ptx:find("basket") then
                    -- skip Give Seed basket
                elseif self:DistanceTo(p) <= range then
                    if self:FireFarm(p, range) then
                        n = n + 1
                        self.PlantCount = (self.PlantCount or 0) + 1
                        farmWorked = true
                        -- After plant, SELECT FERTILIZER opens — must click tier card
                        if Config.AutoFertilizer and not self.FertBusy then
                            -- async: never block Heartbeat Tick with task.wait
                            self.FertBusy = true
                            task.spawn(function()
                                task.wait(0.3)
                                local picked = false
                                local tries = (Config.PerformanceMode ~= false) and 3 or 5
                                for _ = 1, tries do
                                    if HubInstance.stopped then break end
                                    picked = self:SelectFertilizerGUI()
                                    if picked then break end
                                    task.wait(0.18)
                                end
                                self.LastFert = tick()
                                self.FertBusy = false
                                if picked then
                                    local tnow = tick()
                                    self.LastFertToast = self.LastFertToast or 0
                                    if tnow - self.LastFertToast > 4 then
                                        self.LastFertToast = tnow
                                        Toast:Show("Plant + Fert (" .. (Config.FertilizerType or "Basic") .. ")", "ok")
                                    end
                                end
                            end)
                        end
                    end
                end
            end
            if n > 0 then self:NoteSuccess() end
        end
        self.LastPlant = now
    end

    -- 4) FERTILIZER GUI — always try to close SELECT FERTILIZER if open
    if needFert then
        local picked = self:SelectFertilizerGUI()
        if picked then
            self:NoteSuccess()
            farmWorked = true
            self.LastFertToast = self.LastFertToast or 0
            if now - self.LastFertToast > 3 then
                self.LastFertToast = now
                Toast:Show("Fertilizer: " .. (Config.FertilizerType or "Basic"), "ok")
            end
        elseif #fertList > 0 then
            self:SortByDistance(fertList)
            local fertRange = math.min(farmRange or 60, Config.FertilizerPreferNear and 45 or 80)
            local chosen = fertList[1]
            for _, p in ipairs(fertList) do
                local _, _, tx = self:TextOf(p)
                if not (tx:find("give") or tx:find("plant seed") or tx:find("basket"))
                    and self:DistanceTo(p) <= fertRange then
                    chosen = p
                    break
                end
            end
            if chosen and self:FireFarm(chosen, fertRange) then
                task.wait(0.25)
                if self:SelectFertilizerGUI() then
                    self:NoteSuccess()
                    farmWorked = true
                end
            end
        end
        self.LastFert = now
    end

    -- 5) SELL — prefer top-bar SELL GUI (no TP / no other plots)
    if needSell then
        local sold = false
        pcall(function()
            local pg = Player:FindFirstChild("PlayerGui")
            if not pg then return end
            for _, gui in ipairs(pg:GetDescendants()) do
                if gui:IsA("TextButton") or gui:IsA("ImageButton") then
                    local t = ((gui.Text or "") .. " " .. (gui.Name or "")):lower():gsub("%s+", " ")
                    if t == "sell" or (t:find("sell") and not t:find("seed") and not t:find("buy")) then
                        if self:ClickGui(gui) then
                            sold = true
                            break
                        end
                    end
                end
            end
        end)
        if not sold and #sellList > 0 then
            self:SortByDistance(sellList)
            local p = sellList[1]
            local range = Config.SellRange or 80
            -- shop sell is not on garden plot
            if self:FireFarm(p, range, { skipOwnCheck = true }) then
                sold = true
            end
        end
        if sold then
            self.SellCount = (self.SellCount or 0) + 1
            self:NoteSuccess()
            farmWorked = true
            self.LastSellToast = self.LastSellToast or 0
            if now - self.LastSellToast > 4 then
                self.LastSellToast = now
                Toast:Show("Sold", "ok")
            end
        end
        self.LastSell = now
    end

    -- 6) BUY (after farm work; still runs if farm idle or always when due)
    if needBuy and #buyList > 0 and not self.Busy then
        self:SortBuyList(buyList)
        local limit = math.max(1, math.min(Config.BuyPerCycle or 1, 5))
        local bought = 0
        local names = {}
        for i = 1, #buyList do
            if bought >= limit then break end
            local p = buyList[i]
            if self:CanAfford(p) then
                local ok = self:FireBuy(p)
                if ok then bought = bought + 1
                    self.BuyCount = (self.BuyCount or 0) + 1
                    local _, _, rawName = self:TextOf(p)
                    local short = self:CleanSeedName(rawName)
                    if short ~= "" then names[#names + 1] = short end
                    task.wait(0.1)
                end
            end
        end
        if bought > 0 then
            self:NoteSuccess()
            self.LastBuyToast = self.LastBuyToast or 0
            if now - self.LastBuyToast >= 1.6 then
                self.LastBuyToast = now
                if #names == 1 then
                    Toast:Show("Bought " .. names[1], "ok")
                else
                    Toast:Show(string.format("Bought ×%d", bought), "ok")
                end
            end
        end
        self.LastBuy = now
    elseif needBuy then
        self.LastBuy = now
    end

    -- REBIRTH (slow)
    if Config.AutoRebirth and (now - (self.LastRebirth or 0) >= 4) then
        for _, prompt in ipairs(alive) do
            if self:IsRebirthPrompt(prompt) then
                self:FireNear(prompt, 25)
                self.LastRebirth = now
                break
            end
        end
        pcall(function()
            local pg = Player:FindFirstChild("PlayerGui")
            if not pg then return end
            for _, gui in ipairs(pg:GetDescendants()) do
                if gui:IsA("TextButton") or gui:IsA("ImageButton") then
                    local t = ((gui.Text or "") .. " " .. (gui.Name or "")):lower()
                    if t:find("rebirth") or t:find("prestige") then
                        pcall(function() firesignal(gui.MouseButton1Click) end)
                        self.LastRebirth = now
                        break
                    end
                end
            end
        end)
    end

    -- PETS: Feed hungry pets
    if Config.AutoFeedPet and (now - (self.LastFeedPet or 0) >= 2.2) then
        local fed = self:RunFeedPets(alive)
        if fed > 0 then
            self:NoteSuccess()
            self.LastFeedToast = self.LastFeedToast or 0
            if now - self.LastFeedToast > 4 then
                self.LastFeedToast = now
                Toast:Show(string.format("Fed pet ×%d", fed), "ok")
            end
        end
        self.LastFeedPet = now
    end

    -- PETS: Place / hatch egg
    if Config.AutoPlaceEgg and (now - (self.LastEgg or 0) >= 2.0) then
        local eRange = Config.EggRange or 40
        for _, prompt in ipairs(alive) do
            if self:IsEggPrompt(prompt) and self:DistanceTo(prompt) <= eRange then
                if self:FireFarm(prompt, eRange) then
                    self:NoteSuccess()
                    self.LastEggToast = self.LastEggToast or 0
                    if now - self.LastEggToast > 4 then
                        self.LastEggToast = now
                        Toast:Show("Placed Egg", "ok")
                    end
                    break
                end
            end
        end
        self.LastEgg = now
    end

    -- PETS: Equip
    if Config.AutoEquipPet and (now - (self.LastPetEquip or 0) >= 3.0) then
        local did = false
        for _, prompt in ipairs(alive) do
            if self:IsPetEquipPrompt(prompt) and self:DistanceTo(prompt) <= 40 then
                if self:FireFarm(prompt, 40) then
                    did = true
                    self:NoteSuccess()
                    break
                end
            end
        end
        if not did then
            pcall(function()
                local pg = Player:FindFirstChild("PlayerGui")
                if not pg then return end
                for _, gui in ipairs(pg:GetDescendants()) do
                    if gui:IsA("TextButton") or gui:IsA("ImageButton") then
                        local t = ((gui.Text or "") .. " " .. (gui.Name or "")):lower()
                        if t:find("equip") and (t:find("pet") or t:find("slot")) then
                            pcall(function() firesignal(gui.MouseButton1Click) end)
                            did = true
                            self:NoteSuccess()
                            break
                        end
                    end
                end
            end)
        end
        self.LastPetEquip = now
    end
end

function FeatureEngine:Start()
    if self.Running then return end
    self.Running = true
    self:RefreshCache()
    self.LastTick = 0
    if self.Connection then
        pcall(function() self.Connection:Disconnect() end)
        self.Connection = nil
    end
    self.Connection = RunService.Heartbeat:Connect(function()
        if HubInstance.stopped then return end
        local nFeat = 0
        if Config.AutoBuy then nFeat = nFeat + 1 end
        if Config.AutoPlant then nFeat = nFeat + 1 end
        if Config.AutoHarvest then nFeat = nFeat + 1 end
        if Config.AutoCollect then nFeat = nFeat + 1 end
        if Config.AutoSell then nFeat = nFeat + 1 end
        if Config.AutoFertilizer then nFeat = nFeat + 1 end
        if Config.AutoRebirth then nFeat = nFeat + 1 end
        if Config.AutoFeedPet then nFeat = nFeat + 1 end
        if Config.AutoPlaceEgg then nFeat = nFeat + 1 end
        if Config.AutoEquipPet then nFeat = nFeat + 1 end
        if nFeat == 0 then return end
        local now = tick()
        -- adaptive interval: more features ON → slower tick → less lag
        local iv = self.TickInterval or 0.35
        if Config.PerformanceMode ~= false then
            if nFeat >= 6 then iv = 0.55
            elseif nFeat >= 4 then iv = 0.42
            else iv = 0.32 end
        end
        if Config.IdleThrottle and (now - (self.LastActionAt or 0)) > 6 then
            iv = math.max(iv, 0.65)
        end
        if self.FertBusy then
            iv = math.max(iv, 0.5) -- don't stack work while fert panel is being clicked
        end
        if now - (self.LastTick or 0) < iv then return end
        self.LastTick = now
        -- Frame budget: cap Tick execution to ~12ms per frame to prevent lag spikes
        local tickStart = os.clock()
        local TICK_BUDGET = 0.012
        self:Tick()
        local elapsed = os.clock() - tickStart
        if elapsed > TICK_BUDGET then
            -- Over budget: increase interval next frame to compensate
            self.LastTick = now + (elapsed - TICK_BUDGET)
        end
        -- Cleanup stale RecentBuys every 10 seconds to prevent memory leak
        if not self._lastCleanup or (now - self._lastCleanup) > 10 then
            self._lastCleanup = now
            local cutoff = now - 5
            for k, v in pairs(self.RecentBuys or {}) do
                if v < cutoff then self.RecentBuys[k] = nil end
            end
        end
    end)
    HubInstance:AddConnection(self.Connection)
end

function FeatureEngine:Stop()
    if self.Connection then
        self.Connection:Disconnect()
        self.Connection = nil
    end
    self.Running = false
    self.PromptCache = {}
    self.Busy = false
end

function FeatureEngine:EnsureRunning()
    local any = Config.AutoBuy or Config.AutoPlant or Config.AutoHarvest
        or Config.AutoCollect or Config.AutoSell or Config.AutoRebirth or Config.AutoFertilizer
        or Config.AutoPlaceEgg or Config.AutoEquipPet or Config.AutoFeedPet
    if any and not self.Running then
        self:Start()
    elseif not any and self.Running then
        self:Stop()
    end
end

function FeatureEngine:IsRebirthPrompt(prompt)
    local action, object, text = self:TextOf(prompt)
    if text:find("give seed") or text:find("plant seed") or text:find("sell") or text:find("harvest") then
        return false
    end
    return text:find("rebirth") ~= nil or text:find("prestige") ~= nil
        or action:find("rebirth") ~= nil or object:find("rebirth") ~= nil
end

-- Feed hungry pet (prompt: Feed / Hungry / Give Food)
function FeatureEngine:IsFeedPetPrompt(prompt)
    local action, object, text = self:TextOf(prompt)
    if text:find("give seed") or text:find("plant seed") or text:find("buy") then return false end
    if text:find("harvest") or text:find("sell") or text:find("fertiliz") then return false end
    if text:find("pick up") or text:find("pickup") then return false end
    if text:find("feed") or action:find("feed") or object:find("feed") then return true end
    if text:find("hungry") then return true end
    return false
end

function FeatureEngine:CountFruitEffects(text)
    text = (text or ""):lower()
    local tags = {
        "shocked", "radioactive", "charged", "golden", "rainbow", "frozen",
        "wet", "chilled", "cooked", "burnt", "moonlit", "bloodlit", "celestial",
        "disco", "plasma", "void", "infested", "slimy", "huge", "scaled",
        "dewy", "lucky", "galactic", "aurora", "zombified", "honey",
    }
    local n = 0
    for _, tag in ipairs(tags) do
        if text:find(tag, 1, true) then n = n + 1 end
    end
    return n
end

function FeatureEngine:IsHighRarityFruitText(text)
    text = (text or ""):lower()
    if text:find("mythic") or text:find("legendary") or text:find("divine") then return true end
    if text:find("secret") or text:find("celestial") or text:find("prismatic") then return true end
    if text:find("spirit fruit") or text:find("astral") or text:find("inferno") then return true end
    if text:find("dragon fruit") or text:find("void fruit") or text:find("diamond fruit") then return true end
    if text:find("glowing fruit") or text:find("money fruit") then return true end
    return false
end

-- Junk feed fruit: < 2 effects and not high-rarity
function FeatureEngine:IsJunkFeedFruit(text)
    text = (text or ""):lower()
    if text == "" then return false end
    if text:find("feed") or text:find("pick") or text:find("view") or text:find("slot") then return false end
    if self:IsHighRarityFruitText(text) then return false end
    local maxFx = Config.FeedMaxEffects or 1
    if self:CountFruitEffects(text) > maxFx then return false end
    if text:find("fruit") or text:find("apple") or text:find("orange") or text:find("peach")
        or text:find("lemon") or text:find("mango") or text:find("cherry") or text:find("banana")
        or text:find("fig") or text:find("acorn") or text:find("pinecone") or text:find("coconut")
        or text:find("mushroom") or text:find("pizza") or text:find("avocado") or text:find("starfruit") then
        return true
    end
    if text:find("common") then return true end
    return false
end

function FeatureEngine:SelectJunkFruitsForFeed()
    local pg = Player:FindFirstChild("PlayerGui")
    if not pg then return 0 end
    local picked = 0
    local maxPick = Config.FeedMaxFruits or 8
    local candidates = {}
    pcall(function()
        for _, gui in ipairs(pg:GetDescendants()) do
            if gui:IsA("TextButton") or gui:IsA("ImageButton") or gui:IsA("TextLabel") or gui:IsA("ImageLabel") then
                local t = ((gui.Text or "") .. " " .. (gui.Name or "")):lower()
                if t:find("feed all") or t:find("pick up") or t:find("view") or t:find("hunger")
                    or t:find("level") or t:find("active pet") then
                    -- skip chrome
                elseif self:IsJunkFeedFruit(t) then
                    local score = self:CountFruitEffects(t)
                    candidates[#candidates + 1] = { gui = gui, score = score }
                end
            end
        end
        table.sort(candidates, function(a, b) return a.score < b.score end)
        for _, c in ipairs(candidates) do
            if picked >= maxPick then break end
            local target = c.gui
            if target:IsA("TextLabel") or target:IsA("ImageLabel") then
                target = self:FindClickableAncestor(target) or target
            end
            if self:ClickGui(target) then
                picked = picked + 1
                task.wait(0.08)
            end
        end
    end)
    return picked
end

-- FEED ALL (ACTIVE PETS panel + world) → junk fruit only
function FeatureEngine:RunFeedPets(alive)
    local fed = 0
    local range = Config.FeedPetRange or 45
    alive = alive or self.PromptCache or {}
    local pg = Player:FindFirstChild("PlayerGui")

    -- 1) GUI first: every "FEED ALL" on ACTIVE PETS (no TP)
    if pg then
        pcall(function()
            local buttons = {}
            for _, gui in ipairs(pg:GetDescendants()) do
                if gui:IsA("TextButton") or gui:IsA("ImageButton") then
                    local t = ((gui.Text or "") .. " " .. (gui.Name or "")):lower():gsub("%s+", " ")
                    if t == "feed all" or t:find("feed all", 1, true) then
                        buttons[#buttons + 1] = gui
                    end
                end
            end
            for _, btn in ipairs(buttons) do
                if self:ClickGui(btn) then
                    fed = fed + 1
                    task.wait(0.35)
                    self:SelectJunkFruitsForFeed()
                    task.wait(0.15)
                end
            end
        end)
    end

    -- 2) World billboard near pets on own plot
    if fed == 0 then
        for _, prompt in ipairs(alive) do
            if self:IsFeedPetPrompt(prompt) and self:DistanceTo(prompt) <= range then
                if self:FireFarm(prompt, range) then
                    fed = fed + 1
                    task.wait(0.3)
                    self:SelectJunkFruitsForFeed()
                    if fed >= 3 then break end
                end
            end
        end
    end

    -- 3) Still try junk fruit if a feed inventory is open
    if fed > 0 or (pg and true) then
        pcall(function() self:SelectJunkFruitsForFeed() end)
    end
    return fed
end

-- Place / hatch pet egg on plot
function FeatureEngine:IsEggPrompt(prompt)
    local action, object, text = self:TextOf(prompt)
    if text:find("give seed") or text:find("plant seed") or text:find("buy seed") then return false end
    if text:find("harvest") or text:find("sell") or text:find("fertiliz") then return false end
    if text:find("egg") or object:find("egg") then
        if text:find("place") or text:find("hatch") or text:find("plant")
            or action:find("place") or action:find("hatch") or action:find("use")
            or action:find("plant") or action:find("interact") then
            return true
        end
        -- bare egg interact on plot
        if not text:find("buy") and not text:find("shop") then return true end
    end
    if action:find("hatch") or object:find("petegg") then return true end
    return false
end

-- Equip pet
function FeatureEngine:IsPetEquipPrompt(prompt)
    local action, object, text = self:TextOf(prompt)
    if text:find("give seed") or text:find("plant seed") or text:find("buy") then return false end
    if text:find("egg") and text:find("hatch") then return false end
    if text:find("equip") and (text:find("pet") or object:find("pet")) then return true end
    if action:find("equip") and (text:find("pet") or object:find("pet")) then return true end
    if text:find("pet") and (action:find("equip") or action:find("use") or action:find("place")) then
        return true
    end
    return false
end

function FeatureEngine:IsFertilizerPrompt(prompt)
    local action, object, text = self:TextOf(prompt)
    -- Greedy Growers: fertilizer is mainly the post-plant GUI (SelectFertilizerGUI).
    -- Standalone world prompts are rare — hard-exclude everything that is not fert.
    if text:find("give seed") or (text:find("give") and text:find("seed")) then return false end
    if text:find("plant seed") then return false end
    if text:find("buy") or text:find("sell") or text:find("harvest") or text:find("collect") then return false end
    if text:find("deposit") or text:find("storage") or text:find("basket") then return false end
    if action:find("buy") or action:find("sell") or action:find("plant") or action:find("harvest") or action:find("give") then return false end
    if text:find("fertiliz") or text:find("fertiliser") or text:find("fertilizer")
        or text:find("manure") or text:find("compost") or text:find("nutrient")
        or action:find("fertiliz") or object:find("fertiliz")
        or action:find("fertilizer") or object:find("fertilizer") then
        return true
    end
    return false
end

-- Click a GUI element (button / frame card) via signal + virtual mouse
function FeatureEngine:ClickGui(gui)
    if not gui or not gui.Parent then return false end
    local ok = false
    local light = Config.PerformanceMode ~= false -- default ON = less lag
    pcall(function()
        if gui:IsA("GuiButton") then
            pcall(function() firesignal(gui.MouseButton1Click) end)
            pcall(function() firesignal(gui.Activated) end)
            pcall(function() gui.MouseButton1Click:Fire() end)
            if not light and getconnections then
                pcall(function()
                    for _, conn in ipairs(getconnections(gui.MouseButton1Click)) do
                        pcall(function()
                            if conn.Fire then conn:Fire()
                            elseif conn.Function then conn.Function() end
                        end)
                    end
                end)
            end
            ok = true
        end
        -- child hitboxes (limit count in perf mode)
        local n = 0
        for _, ch in ipairs(gui:GetDescendants()) do
            if ch:IsA("GuiButton") then
                pcall(function() firesignal(ch.MouseButton1Click) end)
                pcall(function() firesignal(ch.Activated) end)
                ok = true
                n = n + 1
                if light and n >= 3 then break end
            end
        end
        -- single virtual click (no double + no long wait)
        local pos = gui.AbsolutePosition + gui.AbsoluteSize / 2
        if pos.X > 1 and pos.Y > 1 and gui.AbsoluteSize.X > 4 then
            local insetY = 0
            pcall(function() insetY = game:GetService("GuiService"):GetGuiInset().Y end)
            pcall(function()
                VirtualInputManager:SendMouseButtonEvent(pos.X, pos.Y + insetY, 0, true, game, 1)
                task.wait(light and 0.02 or 0.04)
                VirtualInputManager:SendMouseButtonEvent(pos.X, pos.Y + insetY, 0, false, game, 1)
            end)
            ok = true
        end
    end)
    return ok
end

function FeatureEngine:FindClickableAncestor(inst, maxDepth)
    maxDepth = maxDepth or 10
    local cur = inst
    for _ = 1, maxDepth do
        if not cur or cur == game then break end
        if cur:IsA("GuiButton") then return cur end
        cur = cur.Parent
    end
    cur = inst
    for _ = 1, maxDepth do
        if not cur or cur == game then break end
        if cur:IsA("Frame") or cur:IsA("ImageLabel") or cur:IsA("ImageButton") then
            local s = cur.AbsoluteSize
            if s.X >= 36 and s.X <= 280 and s.Y >= 36 and s.Y <= 280 then
                return cur
            end
        end
        cur = cur.Parent
    end
    return inst
end

-- Find SELECT FERTILIZER root frame in PlayerGui
function FeatureEngine:GetFertilizerPanel()
    local pg = Player:FindFirstChild("PlayerGui")
    if not pg then return nil end
    local title
    for _, gui in ipairs(pg:GetDescendants()) do
        if gui:IsA("TextLabel") or gui:IsA("TextButton") then
            local t = (gui.Text or ""):lower()
            if t:find("select fertilizer", 1, true) then
                title = gui
                break
            end
        end
    end
    if not title then return nil end
    -- climb to a wide panel frame
    local cur = title
    for _ = 1, 12 do
        if not cur then break end
        if cur:IsA("Frame") or cur:IsA("ImageLabel") then
            local s = cur.AbsoluteSize
            if s.X >= 280 and s.Y >= 120 then
                return cur
            end
        end
        cur = cur.Parent
    end
    return title.Parent
end

-- Click chosen fertilizer tier (Magic/Basic/…) on SELECT FERTILIZER
function FeatureEngine:SelectFertilizerGUI()
    local prefer = (Config.FertilizerType or "Basic"):lower():gsub("%s+", "")
    local TIER_ORDER = { "none", "basic", "better", "premium", "super", "magic" }
    local tierIndex = {}
    for i, n in ipairs(TIER_ORDER) do tierIndex[n] = i end
    local wantIdx = tierIndex[prefer] or 2

    local pg = Player:FindFirstChild("PlayerGui")
    if not pg then return false end

    local function panelStillOpen()
        for _, gui in ipairs(pg:GetDescendants()) do
            if gui:IsA("TextLabel") or gui:IsA("TextButton") then
                local t = (gui.Text or ""):lower()
                if t:find("select fertilizer", 1, true) then return true end
            end
        end
        return false
    end

    local function clickTierByLabel(want)
        local panel = self:GetFertilizerPanel()
        local roots = panel and { panel } or { pg }
        for _, root in ipairs(roots) do
            for _, gui in ipairs(root:GetDescendants()) do
                if gui:IsA("TextLabel") or gui:IsA("TextButton") or gui:IsA("TextBox") then
                    local t = ((gui.Text or ""):lower()):gsub("%s+", "")
                    if t == want or t == want .. "fertilizer" then
                        if want ~= "none" and (t:find("worm") or t:find("lucky") or t:find("dewy")) then
                            -- skip
                        else
                            local card = self:FindClickableAncestor(gui)
                            self:ClickGui(card)
                            self:ClickGui(gui)
                            -- click every button under same parent card
                            if card and card.Parent then
                                for _, ch in ipairs(card:GetDescendants()) do
                                    if ch:IsA("GuiButton") then self:ClickGui(ch) end
                                end
                            end
                            task.wait(0.15)
                            if not panelStillOpen() then return true end
                            -- panel may stay open until confirm — treat click as success if preferred
                            return true
                        end
                    end
                end
            end
            -- Name match on buttons/frames
            for _, gui in ipairs(root:GetDescendants()) do
                local n = (gui.Name or ""):lower():gsub("%s+", "")
                if n == want or n:find(want, 1, true) then
                    if gui:IsA("GuiButton") or gui:IsA("Frame") or gui:IsA("ImageLabel") then
                        if not n:find("worm") then
                            self:ClickGui(gui)
                            task.wait(0.12)
                            return true
                        end
                    end
                end
            end
        end
        return false
    end

    -- Fallback: sort jar cards left→right under panel, click index
    local function clickTierByPosition(idx)
        local panel = self:GetFertilizerPanel()
        if not panel then return false end
        local cards = {}
        for _, gui in ipairs(panel:GetDescendants()) do
            if gui:IsA("GuiButton") or gui:IsA("Frame") or gui:IsA("ImageButton") then
                local s = gui.AbsoluteSize
                -- jar card size roughly square / portrait
                if s.X >= 50 and s.X <= 140 and s.Y >= 60 and s.Y <= 180 then
                    local hasJar = false
                    for _, ch in ipairs(gui:GetDescendants()) do
                        if ch:IsA("ImageLabel") or ch:IsA("ImageButton") then hasJar = true; break end
                    end
                    if hasJar or gui:IsA("GuiButton") then
                        cards[#cards + 1] = gui
                    end
                end
            end
        end
        table.sort(cards, function(a, b)
            return a.AbsolutePosition.X < b.AbsolutePosition.X
        end)
        -- unique by X roughly
        local unique = {}
        local lastX = -9999
        for _, c in ipairs(cards) do
            if c.AbsolutePosition.X - lastX > 20 then
                unique[#unique + 1] = c
                lastX = c.AbsolutePosition.X
            end
        end
        local target = unique[idx]
        if not target and #unique > 0 then target = unique[math.clamp(idx, 1, #unique)]
        end
        if target then
            self:ClickGui(target)
            task.wait(0.12)
            return true
        end
        return false
    end

    local clicked = false
    local maxTry = (Config.PerformanceMode ~= false) and 3 or 6
    pcall(function()
        for attempt = 1, maxTry do
            if not panelStillOpen() and attempt > 1 then break end
            if clickTierByLabel(prefer) then
                clicked = true
                break
            end
            if clickTierByPosition(wantIdx) then
                clicked = true
                break
            end
            task.wait(0.12)
        end
        if not clicked and panelStillOpen() and Config.FertilizerSoftFallback ~= false then
            for _, fb in ipairs({ "super", "premium", "better", "basic" }) do
                if fb ~= prefer and clickTierByLabel(fb) then
                    clicked = true
                    break
                end
            end
        end
    end)
    return clicked
end

