-- ========== UI HELPERS ==========
local function CreateElement(class, props)
    local obj = Instance.new(class)
    for k, v in pairs(props or {}) do
        if k ~= "Parent" then
            pcall(function() obj[k] = v end)
        end
    end
    if props.Parent then obj.Parent = props.Parent end
    return obj
end

local function Tween(obj, props, duration, style)
    duration = duration or 0.3
    style = style or Enum.EasingStyle.Quad
    return TweenService:Create(obj, TweenInfo.new(duration, style, Enum.EasingDirection.Out), props):Play()
end

local function AddCorner(parent, radius)
    local corner = Instance.new("UICorner")
    corner.CornerRadius = UDim.new(0, radius or 12)
    corner.Parent = parent
    return corner
end

local function AddStroke(parent, color, thickness, transparency)
    local stroke = Instance.new("UIStroke")
    stroke.Color = color or Theme.border
    stroke.Thickness = thickness or 1
    stroke.Transparency = transparency or 0.6
    stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
    stroke.Parent = parent
    return stroke
end

local function AddGlow(parent, color, size)
    local glow = Instance.new("ImageLabel")
    glow.Name = "Glow"
    glow.Size = UDim2.new(1, size or 40, 1, size or 40)
    glow.Position = UDim2.new(0.5, 0, 0.5, 0)
    glow.AnchorPoint = Vector2.new(0.5, 0.5)
    glow.BackgroundTransparency = 1
    glow.Image = "rbxassetid://6022668907"
    glow.ImageColor3 = color or Theme.accent1
    glow.ImageTransparency = 0.5
    glow.ScaleType = Enum.ScaleType.Slice
    glow.SliceCenter = Rect.new(100, 100, 100, 100)
    glow.ZIndex = 0
    glow.Parent = parent
    return glow
end

local function AddGloss(parent, intensity)
    -- Top glossy highlight
    local gloss = Instance.new("Frame")
    gloss.Name = "Gloss"
    gloss.Size = UDim2.new(1, 0, 0.5, 0)
    gloss.Position = UDim2.new(0, 0, 0, 0)
    gloss.BackgroundColor3 = Theme.gloss
    gloss.BackgroundTransparency = intensity or 0.85
    gloss.BorderSizePixel = 0
    gloss.ZIndex = 10
    gloss.Parent = parent
    
    AddCorner(gloss, parent:FindFirstChildOfClass("UICorner") and parent:FindFirstChildOfClass("UICorner").CornerRadius.Offset or 12)
    
    local gradient = Instance.new("UIGradient")
    gradient.Color = ColorSequence.new(Color3.fromRGB(255, 255, 255))
    gradient.Rotation = 90
    gradient.Transparency = NumberSequence.new({
        NumberSequenceKeypoint.new(0, 0),
        NumberSequenceKeypoint.new(0.5, 0.3),
        NumberSequenceKeypoint.new(1, 1)
    })
    gradient.Parent = gloss
    
    return gloss
end

local function AddInnerShadow(parent, depth)
    -- Bottom shadow for depth
    local shadow = Instance.new("Frame")
    shadow.Name = "InnerShadow"
    shadow.Size = UDim2.new(1, 0, 0, depth or 3)
    shadow.Position = UDim2.new(0, 0, 1, -(depth or 3))
    shadow.BackgroundColor3 = Theme.shadow
    shadow.BackgroundTransparency = 0.6
    shadow.BorderSizePixel = 0
    shadow.ZIndex = 10
    shadow.Parent = parent
    
    local gradient = Instance.new("UIGradient")
    gradient.Rotation = 90
    gradient.Transparency = NumberSequence.new({
        NumberSequenceKeypoint.new(0, 1),
        NumberSequenceKeypoint.new(1, 0)
    })
    gradient.Parent = shadow
    
    return shadow
end

