    })

    local function makeDot(px, py)
        local f = CreateElement("Frame", {
            Size = UDim2.new(0, 0, 0, 0),
            Position = UDim2.new(0, px, 0, py),
            AnchorPoint = Vector2.new(0.5, 0.5),
