            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            ZIndex = 52,
            Parent = mark
        })
        AddCorner(f, 99)
        return f
    end

    -- 4 toes in arc + pad
    --        o  o
    --      o      o
    --         ██
    local toeSpecs = {
        {x = 12, y = 14, w = 11, h = 14},
        {x = 22, y = 8,  w = 12, h = 15},
        {x = 34, y = 8,  w = 12, h = 15},
        {x = 44, y = 14, w = 11, h = 14},
    }
    local toes = {}
    for i, d in ipairs(toeSpecs) do
        local f = makeDot(d.x, d.y)
        toes[i] = {f = f, w = d.w, h = d.h}
    end
    local pad = makeDot(28, 36)
    AddCorner(pad, 12)

    -- Wordmark cells equal width
    local word = CreateElement("Frame", {
        Size = UDim2.new(0, 120, 0, 40),
